SET claim_state = 'DONE', decided_at = NOW(), update_time = NOW()
WHERE target_type = #{targetType}
  AND target_id = #{targetId}
  AND review_round <> #{reviewRound}
  AND claim_state IN ('PENDING', 'CLAIMED')

