  AND claim_state IN ('PENDING', 'CLAIMED')

mapper.select:
SELECT task_id FROM review_task WHERE claim_state = 'PENDING'
AND target_type = #{targetType}
ORDER BY entered_at ASC, id ASC LIMIT 1

SELECT claim_seq
FROM review_task
WHERE task_id = #{taskId}

