mapper.select:
SELECT rt.target_type AS targetType, rt.target_id AS targetId, rt.review_round AS reviewRound, rt.author_id AS authorId, rt.entered_at AS enteredAt FROM review_task rt WHERE rt.claim_state = 'PENDING'
AND rt.target_type = #{targetType}
ORDER BY rt.entered_at ASC, rt.id ASC LIMIT #{offset}, #{limit}

SELECT task_id, target_type, target_id, review_round, author_id, source, claim_state, claim_by, claim_seq,
       lease_expire_at, recycle_count, escalated, entered_at, decided_at, create_time, update_time
FROM review_task
WHERE target_type = #{targetType}
  AND target_id = #{targetId}
  AND claim_state = 'CLAIMED'
  AND claim_by = #{claimBy}
ORDER BY id DESC
LIMIT 1

